  source_specs JSONB,
  backfilled_at  TIMESTAMPTZ,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_sound_av_profile_service
  ON public.partner_sound_av_profiles (service_id) WHERE service_id IS NOT NULL;
