         WHERE c.table_schema = 'public' AND c.table_name = t.table_name) AS columns
  FROM information_schema.tables t
 WHERE table_schema = 'public' AND table_name IN ('partner_sound_av_profiles', 'partner_sound_av_items', 'partner_tent_furniture_profiles', 'partner_tent_furniture_items', 'partner_transportation_profiles', 'partner_trousseau_gift_packing_profiles', 'partner_trousseau_gift_packing_items', 'partner_valet_parking_profiles', 'partner_venue_profiles', 'partner_venue_items')
 ORDER BY table_name;
